def p(text='', style=None, align=None, bold=False):
    x=doc.add_paragraph(style=style); x.alignment=align
    r=x.add_run(text); r.bold=bold; r.font.name='Times New Roman'; r.font.size=Pt(12)
    return x
def centered(text, size=12, bold=False):
    x=doc.add_paragraph(); x.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=x.add_run(text); r.bold=bold; r.font.name='Times New Roman'; r.font.size=Pt(size); return x
def page(): doc.add_page_break()
def table(headers, rows):
    t=doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; c.text=h; c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        for r in c.paragraphs[0].runs: r.bold=True
    for row in rows:
        cells=t.add_row().cells
        for i,v in enumerate(row): cells[i].text=str(v); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    return t
